import { IconSearch } from "@tabler/icons-react";

import { Button } from "@/components/ui/button";

type CatalogSearchFormProps = {
  defaultQuery: string;
};

export function CatalogSearchForm({ defaultQuery }: CatalogSearchFormProps) {
  return (
    <form action="/catalog" method="get" className="flex gap-2 rounded-xl border border-border/60 bg-card/80 p-2 shadow-sm">
      <div className="flex flex-1 items-center gap-2 rounded-lg px-2">
        <IconSearch className="size-4 text-muted-foreground" />
        <input
          name="q"
          defaultValue={defaultQuery}
          placeholder="Search by part name or OEM"
          className="h-10 w-full bg-transparent text-sm outline-none"
        />
      </div>
      <Button type="submit" className="h-10 px-4">
        Search
      </Button>
    </form>
  );
}
