import { prisma } from "@/lib/db";

import { fallbackCars, fallbackCategories, fallbackParts } from "./catalog-fallback";

export type CatalogPart = {
  id: string;
  slug: string;
  title: string;
  oemNumber: string;
  description: string | null;
  category: {
    name: string;
    slug: string;
  };
  priceFrom: number | null;
  inStock: boolean;
  imageUrl: string | null;
  compatibleCars: Array<{
    slug: string;
    fullName: string;
  }>;
};

export type CatalogCategory = {
  id: string;
  name: string;
  slug: string;
  partsCount: number;
};

export type CatalogCar = {
  id: string;
  slug: string;
  fullName: string;
  brandName: string;
};

type ListPartsInput = {
  query?: string;
  categorySlug?: string;
  carSlug?: string;
};

type DbPart = {
  id: string;
  slug: string;
  title: string;
  oemNumber: string;
  description: string | null;
  priceFrom: number | null;
  inStock: boolean;
  category: {
    name: string;
    slug: string;
  };
  images: Array<{
    url: string;
  }>;
  compatibilities: Array<{
    car: {
      slug: string;
      model: string;
      generation: string | null;
      brand: {
        name: string;
      };
    };
  }>;
};

type DbCategory = {
  id: string;
  name: string;
  slug: string;
  _count: {
    parts: number;
  };
};

type DbCar = {
  id: string;
  slug: string;
  model: string;
  generation: string | null;
  brand: {
    name: string;
  };
};

function buildCarName(brand: string, model: string, generation: string | null) {
  return [brand, model, generation].filter(Boolean).join(" ");
}

function mapFallbackPart(partSlug: string): CatalogPart | null {
  const part = fallbackParts.find((entry) => entry.slug === partSlug);
  if (!part) {
    return null;
  }

  return {
    id: part.id,
    slug: part.slug,
    title: part.title,
    oemNumber: part.oemNumber,
    description: part.description,
    category: {
      name: part.category.name,
      slug: part.category.slug,
    },
    priceFrom: part.priceFrom,
    inStock: part.inStock,
    imageUrl: part.imageUrl,
    compatibleCars: part.carSlugs
      .map((slug) => fallbackCars.find((car) => car.slug === slug))
      .filter((car): car is (typeof fallbackCars)[number] => Boolean(car))
      .map((car) => ({
        slug: car.slug,
        fullName: buildCarName(car.brand.name, car.model, car.generation),
      })),
  };
}

function listFallbackParts(input: ListPartsInput = {}) {
  const normalizedQuery = input.query?.trim().toLowerCase() ?? "";

  let filtered = fallbackParts;

  if (input.categorySlug) {
    filtered = filtered.filter((part) => part.category.slug === input.categorySlug);
  }

  if (input.carSlug) {
    filtered = filtered.filter((part) => part.carSlugs.includes(input.carSlug!));
  }

  if (normalizedQuery) {
    filtered = filtered.filter((part) => {
      return (
        part.title.toLowerCase().includes(normalizedQuery) ||
        part.oemNumber.toLowerCase().includes(normalizedQuery)
      );
    });
  }

  return filtered.map((part) => mapFallbackPart(part.slug)).filter((part): part is CatalogPart => Boolean(part));
}

function listFallbackCategories(): CatalogCategory[] {
  return fallbackCategories.map((category) => ({
    id: category.id,
    name: category.name,
    slug: category.slug,
    partsCount: fallbackParts.filter((part) => part.category.slug === category.slug).length,
  }));
}

function listFallbackCars(): CatalogCar[] {
  return fallbackCars.map((car) => ({
    id: car.id,
    slug: car.slug,
    fullName: buildCarName(car.brand.name, car.model, car.generation),
    brandName: car.brand.name,
  }));
}

export async function listCatalogParts(input: ListPartsInput = {}): Promise<CatalogPart[]> {
  const normalizedQuery = input.query?.trim() ?? "";

  try {
    const parts = (await prisma.part.findMany({
      where: {
        ...(input.categorySlug
          ? {
              category: {
                slug: input.categorySlug,
              },
            }
          : {}),
        ...(input.carSlug
          ? {
              compatibilities: {
                some: {
                  car: {
                    slug: input.carSlug,
                  },
                },
              },
            }
          : {}),
        ...(normalizedQuery
          ? {
              OR: [
                {
                  title: {
                    contains: normalizedQuery,
                    mode: "insensitive",
                  },
                },
                {
                  oemNumber: {
                    contains: normalizedQuery,
                    mode: "insensitive",
                  },
                },
              ],
            }
          : {}),
      },
      include: {
        category: true,
        images: {
          orderBy: {
            sortOrder: "asc",
          },
          take: 1,
        },
        compatibilities: {
          include: {
            car: {
              include: {
                brand: true,
              },
            },
          },
        },
      },
      orderBy: {
        createdAt: "desc",
      },
    })) as DbPart[];

    return parts.map((part) => ({
      id: part.id,
      slug: part.slug,
      title: part.title,
      oemNumber: part.oemNumber,
      description: part.description,
      category: {
        name: part.category.name,
        slug: part.category.slug,
      },
      priceFrom: part.priceFrom,
      inStock: part.inStock,
      imageUrl: part.images[0]?.url ?? null,
      compatibleCars: part.compatibilities.map((compatibility) => ({
        slug: compatibility.car.slug,
        fullName: buildCarName(
          compatibility.car.brand.name,
          compatibility.car.model,
          compatibility.car.generation
        ),
      })),
    }));
  } catch {
    return listFallbackParts(input);
  }
}

export async function listCatalogCategories(): Promise<CatalogCategory[]> {
  try {
    const categories = (await prisma.category.findMany({
      include: {
        _count: {
          select: {
            parts: true,
          },
        },
      },
      orderBy: {
        name: "asc",
      },
    })) as DbCategory[];

    return categories.map((category) => ({
      id: category.id,
      name: category.name,
      slug: category.slug,
      partsCount: category._count.parts,
    }));
  } catch {
    return listFallbackCategories();
  }
}

export async function listCatalogCars(): Promise<CatalogCar[]> {
  try {
    const cars = (await prisma.car.findMany({
      include: {
        brand: true,
      },
      orderBy: [{ brand: { name: "asc" } }, { model: "asc" }],
      take: 12,
    })) as DbCar[];

    return cars.map((car) => ({
      id: car.id,
      slug: car.slug,
      fullName: buildCarName(car.brand.name, car.model, car.generation),
      brandName: car.brand.name,
    }));
  } catch {
    return listFallbackCars();
  }
}

export async function getPartBySlug(slug: string): Promise<CatalogPart | null> {
  try {
    const part = (await prisma.part.findUnique({
      where: { slug },
      include: {
        category: true,
        images: {
          orderBy: {
            sortOrder: "asc",
          },
        },
        compatibilities: {
          include: {
            car: {
              include: {
                brand: true,
              },
            },
          },
        },
      },
    })) as DbPart | null;

    if (!part) {
      return null;
    }

    return {
      id: part.id,
      slug: part.slug,
      title: part.title,
      oemNumber: part.oemNumber,
      description: part.description,
      category: {
        name: part.category.name,
        slug: part.category.slug,
      },
      priceFrom: part.priceFrom,
      inStock: part.inStock,
      imageUrl: part.images[0]?.url ?? null,
      compatibleCars: part.compatibilities.map((compatibility) => ({
        slug: compatibility.car.slug,
        fullName: buildCarName(
          compatibility.car.brand.name,
          compatibility.car.model,
          compatibility.car.generation
        ),
      })),
    };
  } catch {
    return mapFallbackPart(slug);
  }
}

export async function getCarBySlug(slug: string): Promise<CatalogCar | null> {
  try {
    const car = await prisma.car.findUnique({
      where: { slug },
      include: {
        brand: true,
      },
    });

    if (!car) {
      return null;
    }

    return {
      id: car.id,
      slug: car.slug,
      fullName: buildCarName(car.brand.name, car.model, car.generation),
      brandName: car.brand.name,
    };
  } catch {
    const fallbackCar = fallbackCars.find((car) => car.slug === slug);
    if (!fallbackCar) {
      return null;
    }

    return {
      id: fallbackCar.id,
      slug: fallbackCar.slug,
      fullName: buildCarName(fallbackCar.brand.name, fallbackCar.model, fallbackCar.generation),
      brandName: fallbackCar.brand.name,
    };
  }
}
