import type { Metadata } from "next";
import Link from "next/link";

import { CatalogSearchForm } from "@/components/catalog/catalog-search-form";
import { PartsGrid } from "@/components/catalog/parts-grid";
import { Badge } from "@/components/ui/badge";
import { listCatalogCategories, listCatalogParts } from "@/lib/services/catalog";

export const metadata: Metadata = {
  title: "Catalog | Chinalending",
  description: "Chinese auto parts catalog with OEM and model compatibility search.",
};

type CatalogPageProps = {
  searchParams: Promise<{
    q?: string;
  }>;
};

export default async function CatalogPage({ searchParams }: CatalogPageProps) {
  const params = await searchParams;
  const query = params.q?.trim() ?? "";

  const [parts, categories] = await Promise.all([
    listCatalogParts({ query }),
    listCatalogCategories(),
  ]);

  return (
    <div className="mx-auto flex w-full max-w-7xl flex-col gap-6 px-4 py-6 sm:px-6 lg:px-10">
      <section className="space-y-3">
        <p className="text-xs uppercase tracking-[0.2em] text-muted-foreground">Chinalending</p>
        <h1 className="text-2xl font-semibold sm:text-3xl">Auto parts catalog</h1>
        <p className="text-sm text-muted-foreground">Search by part name or OEM number. Open a part page and send request via WhatsApp.</p>
      </section>

      <CatalogSearchForm defaultQuery={query} />

      <section className="flex flex-wrap gap-2">
        {categories.map((category) => (
          <Link key={category.id} href={`/catalog/${category.slug}`}>
            <Badge variant="outline" className="py-1">
              {category.name} · {category.partsCount}
            </Badge>
          </Link>
        ))}
      </section>

      {parts.length ? (
        <PartsGrid parts={parts} />
      ) : (
        <div className="rounded-xl border border-dashed border-border/70 p-8 text-center text-sm text-muted-foreground">
          No parts found for this query. Try another OEM code or open categories.
        </div>
      )}
    </div>
  );
}
